package me.raddatz.veyq.core.crypto

import com.fasterxml.jackson.databind.JsonNode
import com.fasterxml.jackson.databind.ObjectMapper
import org.junit.jupiter.api.Assertions.assertArrayEquals
import org.junit.jupiter.api.Assertions.assertFalse
import org.junit.jupiter.api.Assertions.assertNull
import org.junit.jupiter.api.Assertions.assertTrue
import org.junit.jupiter.api.Test
import java.io.File
import java.util.Base64
import java.util.HexFormat

/**
 * The backend's `join-endorsement` bytes are the contract's (`join_endorsement` in the crypto vectors, generated by an
 * independent Python implementation and asserted by `packages/crypto` too). The server verifies a staged endorsement
 * under the stage's identity over the record digest the client names — the opened record's (ADR 0115 decision 8), which
 * the statement carries as it carried the sealed one's — so a drift between the two stacks refuses every owner's
 * securing that roots a join record — this reddens first.
 */
class JoinEndorsementTest {

    private val vectors: JsonNode = ObjectMapper().readTree(File("../../contracts/crypto/vectors/v1.json"))
    private val e = vectors["join_endorsement"]
    private val tenantId = e["context"]["tenantId"].asText()
    private val userId = e["context"]["userId"].asText()
    private val signerUserId = e["context"]["signerUserId"].asText()
    private val digest = b64(e["record_digest"])
    private val owner = b64(vectors["invite_key"]["owner"]["bundle"])
    private val signature = b64(e["signature"])
    private val other = "c0ffee00-0000-4000-8000-0000000000e0"

    @Test
    fun theStatementIsTheVectorsAndTheOwnersEndorsementVerifies() {
        assertArrayEquals(hex(e["statement"]), JoinEndorsement.statement(tenantId, userId, signerUserId, digest))
        assertTrue(JoinEndorsement.verifies(owner, tenantId, userId, signerUserId, digest, signature))
    }

    @Test
    fun theEndorsementAnswersForNoOtherTenantMemberSignerRecordOrKey() {
        val otherRecord = Base64.getEncoder().encodeToString(hex(e["record_digest"]).also { it[7] = (it[7].toInt() xor 1).toByte() })
        assertFalse(JoinEndorsement.verifies(owner, other, userId, signerUserId, digest, signature))
        assertFalse(JoinEndorsement.verifies(owner, tenantId, other, signerUserId, digest, signature))
        assertFalse(JoinEndorsement.verifies(owner, tenantId, userId, other, digest, signature))
        assertFalse(JoinEndorsement.verifies(owner, tenantId, userId, signerUserId, otherRecord, signature))
        assertFalse(JoinEndorsement.verifies(b64(vectors["join_record"]["joiner_bundle"]), tenantId, userId, signerUserId, digest, signature))
    }

    @Test
    fun aMalformedInputIsFalseNeverAnException() {
        assertNull(JoinEndorsement.statement("not-a-uuid", userId, signerUserId, digest))
        assertNull(JoinEndorsement.statement(tenantId, userId, signerUserId, "not base64!"))
        // A digest that is no SHA-256 — the sealed record itself, say, as the statement was once built over — is malformed.
        assertNull(JoinEndorsement.statement(tenantId, userId, signerUserId, b64(e["sealed_join_record"])))
        assertFalse(JoinEndorsement.verifies(null, tenantId, userId, signerUserId, digest, signature))
        assertFalse(JoinEndorsement.verifies(owner, tenantId, userId, signerUserId, null, signature))
        assertFalse(JoinEndorsement.verifies(owner, tenantId, userId, signerUserId, digest, null))
        assertFalse(JoinEndorsement.verifies(owner, tenantId, userId, signerUserId, digest, "AAAA"))
    }

    private fun hex(n: JsonNode): ByteArray = HexFormat.of().parseHex(n.asText())
    private fun b64(n: JsonNode): String = Base64.getEncoder().encodeToString(hex(n))
}
